/* racemap d3 loader. The build sandbox blocked the cdnjs download, so this shim
 * pulls d3 v7 from the CDN at runtime. If d3 fails to load, the call graph
 * falls back to a deterministic static SVG (see app.js renderGraph()). */
(function () {
  if (window.d3) return;
  var s = document.createElement("script");
  s.src = "https://cdnjs.cloudflare.com/ajax/libs/d3/7.9.0/d3.min.js";
  s.async = false;
  s.onload = function () { window.dispatchEvent(new Event("d3ready")); };
  document.head.appendChild(s);
})();
